import React, { useState, useEffect } from 'react';

// 🟢 App.js එකෙන් එවන ඇත්ත දත්ත (Props) ටික ගන්නවා
export default function TeacherDashboard({ userName, userUsername, subject, email, phone, address, handleLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  
  // App.js එකෙන් එන Subject එක කඩලා ගන්නවා (උදා: "O/L - Mathematics" -> "O/L" සහ "Mathematics")
  const fullSubject = subject || 'Not Set';
  const subjectParts = fullSubject.split(' - ');
  const teachingGrade = subjectParts.length > 1 ? subjectParts[0] : 'General';
  const teachingSubject = subjectParts.length > 1 ? subjectParts[1] : fullSubject;

  const [isEditing, setIsEditing] = useState(false);
  
  // 🟢 Profile එකට පෙන්වන්න ඇත්ත දත්ත ටික State එකට දාගන්නවා
  const [profileData, setProfileData] = useState({ 
      name: userName || '', 
      username: userUsername || '', 
      email: email || '',
      phone: phone || '', 
      address: address || '' 
  });

  // Props වෙනස් වෙද්දී (ලොග් වෙද්දී) Profile Data ටික අලුත් වෙන්න
  useEffect(() => {
    setProfileData({ 
        name: userName || '', 
        username: userUsername || '', 
        email: email || '', 
        phone: phone || '', 
        address: address || '' 
    });
  }, [userName, userUsername, email, phone, address]);

  const handleProfileUpdate = () => {
      alert("✅ Profile details updated successfully!");
      setIsEditing(false);
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            {/* 🟢 Welcome Banner */}
            <div style={{ backgroundColor: '#15803d', padding: '30px', borderRadius: '15px', color: 'white', marginBottom: '30px', boxShadow: '0 4px 15px rgba(21,128,61,0.2)', position: 'relative', overflow: 'hidden' }}>
              <div style={{ position: 'relative', zIndex: 2 }}>
                <h1 style={{ margin: '0 0 10px 0', fontSize: '28px' }}>Welcome back, {profileData.name || userUsername || 'Teacher'}! 👋</h1>
                <p style={{ margin: 0, opacity: 0.9, fontSize: '15px' }}>Content Management System is active. Manage your lessons and activities below.</p>
              </div>
              <div style={{ position: 'absolute', right: '-10px', top: '-40px', fontSize: '150px', opacity: 0.1, zIndex: 1 }}>👨‍🏫</div>
            </div>
            
            {/* 🟢 Overall Stats */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '20px', marginBottom: '30px' }}>
              <DashboardCard title="Active Subject" count={teachingSubject} icon="📚" color="#eff6ff" textColor="#3b82f6" />
              <DashboardCard title="Teaching Grades" count={teachingGrade} icon="🏫" color="#f5f3ff" textColor="#7c3aed" />
              <DashboardCard title="Uploaded Lessons" count="12" icon="📺" color="#f0fdf4" textColor="#15803d" />
              <DashboardCard title="Active Quizzes" count="05" icon="📝" color="#fefce8" textColor="#eab308" />
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '20px' }}>
                
                {/* Recently Uploaded Materials */}
                <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
                    <h3 style={{ margin: '0 0 15px 0', color: '#1e293b' }}>📄 Recently Uploaded Materials</h3>
                    <div style={{ overflowX: 'auto' }}>
                        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
                            <thead>
                                <tr style={{ color: '#64748b', borderBottom: '2px solid #f1f5f9', fontSize: '13px' }}>
                                    <th style={{ paddingBottom: '10px' }}>Lesson Title</th>
                                    <th style={{ paddingBottom: '10px' }}>Grade</th>
                                    <th style={{ paddingBottom: '10px', textAlign: 'right' }}>Date</th>
                                </tr>
                            </thead>
                            <tbody>
                                <tr style={{ borderBottom: '1px solid #f1f5f9', transition: '0.2s' }}>
                                    <td style={{ padding: '15px 0', color: '#1e293b', fontWeight: 'bold', fontSize: '14px' }}>Introduction to {teachingSubject}</td>
                                    <td style={{ padding: '15px 0', color: '#64748b', fontSize: '13px' }}><span style={{ backgroundColor: '#f1f5f9', padding: '4px 8px', borderRadius: '4px' }}>Grade 10</span></td>
                                    <td style={{ padding: '15px 0', color: '#15803d', fontSize: '13px', fontWeight: 'bold', textAlign: 'right' }}>Today</td>
                                </tr>
                                <tr style={{ borderBottom: '1px solid #f1f5f9', transition: '0.2s' }}>
                                    <td style={{ padding: '15px 0', color: '#1e293b', fontWeight: 'bold', fontSize: '14px' }}>Term Test Revision Tute</td>
                                    <td style={{ padding: '15px 0', color: '#64748b', fontSize: '13px' }}><span style={{ backgroundColor: '#f1f5f9', padding: '4px 8px', borderRadius: '4px' }}>Grade 11</span></td>
                                    <td style={{ padding: '15px 0', color: '#15803d', fontSize: '13px', fontWeight: 'bold', textAlign: 'right' }}>Yesterday</td>
                                </tr>
                            </tbody>
                        </table>
                    </div>
                </div>

                {/* Upcoming Classes */}
                <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', display: 'flex', flexDirection: 'column', gap: '15px' }}>
                    <h3 style={{ margin: 0, color: '#1e293b' }}>🏫 Upcoming Classes</h3>
                    <div style={{ padding: '20px', backgroundColor: '#f8fafc', borderRadius: '12px', borderLeft: '5px solid #3b82f6', transition: '0.2s' }}>
                        <p style={{ margin: 0, fontWeight: 'bold', color: '#1e293b', fontSize: '16px' }}>Grade 10 - {teachingSubject}</p>
                        <p style={{ margin: '8px 0 0 0', fontSize: '14px', color: '#64748b', display: 'flex', alignItems: 'center', gap: '8px' }}>🕒 Saturday, 8:00 AM - 10:00 AM</p>
                    </div>
                    <div style={{ padding: '20px', backgroundColor: '#f8fafc', borderRadius: '12px', borderLeft: '5px solid #f59e0b', transition: '0.2s' }}>
                        <p style={{ margin: 0, fontWeight: 'bold', color: '#1e293b', fontSize: '16px' }}>Grade 11 - {teachingSubject}</p>
                        <p style={{ margin: '8px 0 0 0', fontSize: '14px', color: '#64748b', display: 'flex', alignItems: 'center', gap: '8px' }}>🕒 Sunday, 1:00 PM - 4:00 PM</p>
                    </div>
                </div>
            </div>
          </div>
        );

      case 'upload':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ color: '#1e293b', marginBottom: '20px' }}>📤 Upload Lesson Materials</h2>
            <div style={{ backgroundColor: 'white', padding: '35px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', maxWidth: '600px' }}>
                <form style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
                    <div>
                        <label style={labelStyle}>Lesson Title</label>
                        <input type="text" placeholder="e.g. Introduction to Algebra" style={inputStyle} />
                    </div>
                    <div>
                        <label style={labelStyle}>Grade Category</label>
                        <select style={inputStyle}>
                            <option>Grade 9</option>
                            <option>Grade 10</option>
                            <option>Grade 11</option>
                        </select>
                    </div>
                    <div>
                        <label style={labelStyle}>YouTube Video URL</label>
                        <input type="url" placeholder="https://youtube.com/watch?v=..." style={inputStyle} />
                    </div>
                    <div>
                        <label style={labelStyle}>PDF Handout Upload</label>
                        <input type="file" accept=".pdf" style={{...inputStyle, padding: '10px', backgroundColor: '#fff'}} />
                    </div>
                    <button type="button" style={{ padding: '14px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', marginTop: '10px', fontSize: '14px', boxShadow: '0 4px 10px rgba(21,128,61,0.2)' }}>
                        + Publish Lesson
                    </button>
                </form>
            </div>
          </div>
        );

      case 'activities':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ color: '#1e293b', marginBottom: '20px' }}>🎮 Manage Interactive Activities</h2>
            <div style={{ backgroundColor: 'white', padding: '35px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
                <h3 style={{ margin: '0 0 20px 0', color: '#1e293b' }}>Create New Assessment</h3>
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '20px' }}>
                    <button style={actionBtnStyle}>
                        <span style={{ fontSize: '24px', display: 'block', marginBottom: '10px' }}>📝</span> Create MCQ Quiz
                    </button>
                    <button style={actionBtnStyle}>
                        <span style={{ fontSize: '24px', display: 'block', marginBottom: '10px' }}>🧩</span> Create Matching Game
                    </button>
                    <button style={actionBtnStyle}>
                        <span style={{ fontSize: '24px', display: 'block', marginBottom: '10px' }}>✍️</span> Create Fill-in-the-blanks
                    </button>
                </div>
            </div>
          </div>
        );

      case 'profile':
        return (
          <div style={{ animation: 'fadeIn 0.5s' }}>
            <h2 style={{ margin: '0 0 20px 0', color: '#1e293b' }}>👤 My Profile & Security</h2>
            
            <div style={{ display: 'flex', gap: '20px', flexWrap: 'wrap' }}>
                {/* 🟢 Profile Details Form - ඇත්ත දත්ත පෙන්වයි */}
                <div style={{ flex: '1 1 350px', backgroundColor: 'white', padding: '35px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px', borderBottom: '2px solid #f1f5f9', paddingBottom: '10px' }}>
                        <h3 style={{ color: '#15803d', margin: 0 }}>Personal Details</h3>
                        {!isEditing ? 
                            <button onClick={() => setIsEditing(true)} style={editBtnStyle}>✏️ Edit Profile</button> : 
                            <button onClick={handleProfileUpdate} style={saveBtnStyle}>💾 Save</button>
                        }
                    </div>
                    
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                        <div><label style={labelStyle}>Full Name</label><input type="text" value={profileData.name} onChange={(e) => setProfileData({...profileData, name: e.target.value})} disabled={!isEditing} style={inputStyleProfile(isEditing)} /></div>
                        <div><label style={labelStyle}>Username (For Login)</label><input type="text" value={profileData.username} disabled style={{...inputStyleProfile(false), opacity: 0.8, backgroundColor: '#f1f5f9'}} /></div>
                        <div><label style={labelStyle}>Teaching Subject</label><input type="text" value={fullSubject} disabled style={{...inputStyleProfile(false), opacity: 0.8, backgroundColor: '#f1f5f9'}} /></div>
                        <div><label style={labelStyle}>Email Address</label><input type="email" value={profileData.email} onChange={(e) => setProfileData({...profileData, email: e.target.value})} disabled={!isEditing} style={inputStyleProfile(isEditing)} /></div>
                        <div><label style={labelStyle}>Contact Number</label><input type="text" value={profileData.phone} onChange={(e) => setProfileData({...profileData, phone: e.target.value})} disabled={!isEditing} style={inputStyleProfile(isEditing)} /></div>
                        <div><label style={labelStyle}>Residence Address</label><input type="text" value={profileData.address} onChange={(e) => setProfileData({...profileData, address: e.target.value})} disabled={!isEditing} style={inputStyleProfile(isEditing)} /></div>
                    </div>
                </div>

                {/* 🟢 Change Password Section */}
                <div style={{ flex: '1 1 350px', backgroundColor: 'white', padding: '35px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
                    <h3 style={{ margin: '0 0 20px 0', color: '#ef4444', borderBottom: '2px solid #f1f5f9', paddingBottom: '10px' }}>🔑 Change Password</h3>
                    <form style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                        <div>
                            <label style={labelStyle}>Current Password</label>
                            <input type="password" placeholder="Enter current password" style={inputStyle} />
                        </div>
                        <div>
                            <label style={labelStyle}>New Password</label>
                            <input type="password" placeholder="Enter new password" style={inputStyle} />
                        </div>
                        <div>
                            <label style={labelStyle}>Confirm New Password</label>
                            <input type="password" placeholder="Confirm new password" style={inputStyle} />
                        </div>
                        <button type="button" style={{ width: '100%', padding: '12px', backgroundColor: '#1e293b', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', marginTop: '10px', transition: '0.2s' }}>
                            Update Password
                        </button>
                    </form>
                </div>
            </div>
          </div>
        );

      default: return null;
    }
  };

  return (
    <div style={{ display: 'flex', minHeight: '100vh', backgroundColor: '#f8fafc', fontFamily: 'sans-serif' }}>
      
      {/* 🟢 Sidebar */}
      <div style={{ width: '260px', backgroundColor: '#145c2e', color: 'white', padding: '30px 0', display: 'flex', flexDirection: 'column', boxShadow: '4px 0 15px rgba(0,0,0,0.1)' }}>
        <div style={{ padding: '0 25px', marginBottom: '40px', textAlign: 'center' }}>
            <h2 style={{ margin: 0, fontSize: '24px', letterSpacing: '1px' }}>Aura Pen Saku</h2>
            <p style={{ color: '#86efac', margin: '5px 0 0 0', fontSize: '12px', fontWeight: 'bold' }}>TEACHER PORTAL</p>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '5px', padding: '0 15px' }}>
          <SidebarBtn active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon="🏠" text="Dashboard" />
          <SidebarBtn active={activeTab === 'upload'} onClick={() => setActiveTab('upload')} icon="📤" text="Content Manager" />
          <SidebarBtn active={activeTab === 'activities'} onClick={() => setActiveTab('activities')} icon="🎮" text="Manage Activities" />
          <SidebarBtn active={activeTab === 'profile'} onClick={() => setActiveTab('profile')} icon="👤" text="My Profile" />
        </div>
        
        {/* 🟢 Solid Red Logout Button (Student/Admin Style) */}
        <div style={{ marginTop: 'auto', padding: '20px 15px 0 15px' }}>
            <button onClick={handleLogout} style={logoutBtnStyle}>🚪 Logout</button>
        </div>
      </div>
      
      {/* 🟢 Main Content Area */}
      <div style={{ flex: 1, padding: '40px 50px', overflowY: 'auto' }}>
        {renderContent()}
      </div>

    </div>
  );
}

// 🟢 Reusable Components & Styles
const SidebarBtn = ({ active, onClick, icon, text }) => (
  <button onClick={onClick} style={{ width: '100%', textAlign: 'left', padding: '14px 20px', backgroundColor: active ? 'rgba(255,255,255,0.15)' : 'transparent', color: 'white', border: 'none', borderRadius: '10px', cursor: 'pointer', fontSize: '15px', display: 'flex', alignItems: 'center', gap: '15px', fontWeight: active ? 'bold' : 'normal', transition: '0.2s' }}>
    <span style={{ fontSize: '18px' }}>{icon}</span> {text}
  </button>
);

const DashboardCard = ({ title, count, icon, color, textColor }) => (
  <div style={{ backgroundColor: 'white', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', display: 'flex', alignItems: 'center', justifyContent: 'space-between', borderLeft: `5px solid ${textColor}` }}>
    <div>
      <p style={{ margin: '0 0 5px 0', color: '#64748b', fontSize: '13px', fontWeight: 'bold' }}>{title}</p>
      <h2 style={{ margin: 0, color: '#1e293b', fontSize: '24px' }}>{count}</h2>
    </div>
    <div style={{ width: '60px', height: '60px', borderRadius: '12px', backgroundColor: color, display: 'flex', justifyContent: 'center', alignItems: 'center', fontSize: '28px' }}>{icon}</div>
  </div>
);

const labelStyle = { display: 'block', marginBottom: '8px', color: '#475569', fontSize: '13px', fontWeight: 'bold' };
const inputStyle = { width: '100%', padding: '12px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', outline: 'none', boxSizing: 'border-box', color: '#1e293b', fontSize: '14px', transition: '0.2s' };
const inputStyleProfile = (isEditing) => ({ width: '100%', padding: '12px 15px', borderRadius: '8px', border: isEditing ? '1px solid #3b82f6' : '1px solid #cbd5e1', backgroundColor: isEditing ? 'white' : '#f8fafc', outline: 'none', boxSizing: 'border-box', color: '#1e293b', fontSize: '14px', transition: '0.2s' });
const actionBtnStyle = { flex: 1, padding: '20px', backgroundColor: '#f0fdf4', color: '#15803d', border: '1px solid #bbf7d0', borderRadius: '12px', fontWeight: 'bold', cursor: 'pointer', transition: '0.2s', display: 'flex', flexDirection: 'column', alignItems: 'center' };

// 🟢 Red Logout Button Style
const logoutBtnStyle = { width: '100%', padding: '12px', backgroundColor: '#dc2626', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '15px', display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '10px', transition: '0.2s', boxShadow: '0 4px 10px rgba(220,38,38,0.3)' };

const editBtnStyle = { padding: '8px 16px', backgroundColor: '#f0fdf4', color: '#15803d', border: '1px solid #bbf7d0', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '12px', transition: '0.2s' };
const saveBtnStyle = { padding: '8px 16px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '12px', boxShadow: '0 4px 10px rgba(21,128,61,0.2)' };
